const MIME = {"html": "text/html; charset=utf-8", "js": "application/javascript; charset=utf-8", "json": "application/json", "png": "image/png", "webp": "image/webp"};
function envia(res, nome) {
  const b = ARQ[nome]; if (!b) return false;
  res.set('Content-Type', MIME[nome.split('.').pop()] || 'application/octet-stream');
  res.set('Cache-Control', 'no-cache');
  res.send(Buffer.from(b, 'base64')); return true;
}
// MODO=painel: este mesmo arquivo vira o site do painel (só seu), separado do site do cliente
if (process.env.MODO === 'painel') {
  app.get('/health', (_req, res) => res.json({ ok: true }));
  app.get('/logo.png', (_req, res) => envia(res, 'logo.png'));
  app.use((_req, res) => { res.set('X-Robots-Tag', 'noindex'); envia(res, 'painel.html'); });
}
app.get('/', (_req, res) => envia(res, 'index.html'));
app.get('/app', (_req, res) => envia(res, 'app.html'));
app.get('/:arq', (req, res, next) => { if (req.params.arq === 'painel.html' || !envia(res, req.params.arq)) next(); });

// ===== Códigos de acesso (só quem pagou usa o app e a live) =====
// Configure no Render (Environment): SEGREDO, ADMIN_SENHA e, se quiser bloquear um código, BLOQUEADOS=COD1,COD2
const SEGREDO = process.env.SEGREDO || '';
const ADMIN_SENHA = process.env.ADMIN_SENHA || '';
const BLOQ_COD = () => (process.env.BLOQUEADOS || '').toUpperCase().split(',').map(s => s.trim()).filter(Boolean);
const B32 = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
function assina(nome, val) {
  const h = crypto.createHmac('sha256', SEGREDO).update(nome + '|' + val).digest();
  let o = ''; for (let i = 0; i < 8; i++) o += B32[h[i] % 32]; return o;
}
function limpaNome(n) { return String(n || '').normalize('NFD').replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 12) || 'CLIENTE'; }
function gerarCodigo(nome, dias) {
  const d = new Date(Date.now() + Math.max(1, Math.min(3650, Number(dias) || 30)) * 864e5);
  const val = d.toISOString().slice(2, 10).replace(/-/g, '');
  const n = limpaNome(nome);
  return { codigo: `${n}-${val}-${assina(n, val)}`, validade: d.toISOString().slice(0, 10) };
}
function validaCodigo(c) {
  if (!SEGREDO) return { ok: false, msg: 'Acesso ainda não configurado' };
  const m = String(c || '').trim().toUpperCase().match(/^([A-Z0-9]{1,12})-(\d{6})-([A-Z0-9]{8})$/);
  if (!m) return { ok: false, msg: 'Código inválido' };
  const [, n, val, sig] = m;
  const a = Buffer.from(assina(n, val)), b = Buffer.from(sig);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return { ok: false, msg: 'Código inválido' };
  if (BLOQ_COD().includes(m[0]) || ehBloqueado(m[0])) return { ok: false, msg: 'Código bloqueado' };
  const fim = new Date(`20${val.slice(0, 2)}-${val.slice(2, 4)}-${val.slice(4, 6)}T23:59:59-03:00`);
  if (Date.now() > fim) return { ok: false, msg: 'Código vencido. Renove seu acesso.' };
  return { ok: true, nome: n, validade: `${val.slice(4, 6)}/${val.slice(2, 4)}/20${val.slice(0, 2)}` };
}
const tentativas = new Map();
function limite(ip) { const t = Date.now(), l = (tentativas.get(ip) || []).filter(x => t - x < 60000); l.push(t); tentativas.set(ip, l); return l.length > 20; }
app.use(express.json());
app.post('/api/validar', (req, res) => {
  if (limite(req.ip)) return res.status(429).json({ ok: false, msg: 'Muitas tentativas, espere 1 minuto' });
  res.json(validaCodigo(req.body?.codigo));
});

// ===== Dados do painel (produtos, preços, links, clientes) =====
// Ficam salvos na variável DADOS do próprio Render (via API), pra não perder quando o servidor reinicia.
const PADRAO = { produtos: [{ id: 'p1', nome: 'Acesso completo', descricao: 'Todos os jogos + app com seu @ do TikTok', preco: '', link: '', dias: 30 }], clientes: [], bloqueados: [] };
let DADOS;
try { DADOS = { ...PADRAO, ...JSON.parse(process.env.DADOS || '{}') }; } catch { DADOS = { ...PADRAO }; }
let salvando = null, deNovo = false;
async function salvar() {
  const key = process.env.RENDER_API_KEY, sid = process.env.RENDER_SERVICE_ID;
  if (!key || !sid) return { ok: false, msg: 'Sem RENDER_API_KEY: alterações valem até o servidor reiniciar' };
  if (salvando) { deNovo = true; return salvando; }
  salvando = (async () => {
    try {
      const r = await fetch(`https://api.render.com/v1/services/${sid}/env-vars/DADOS`, {
        method: 'PUT', headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({ value: JSON.stringify(DADOS) })
      });
      return r.ok ? { ok: true } : { ok: false, msg: 'Render recusou salvar (' + r.status + ')' };
    } catch (e) { return { ok: false, msg: 'Falha ao salvar: ' + e.message }; }
    finally { salvando = null; if (deNovo) { deNovo = false; salvar(); } }
  })();
  return salvando;
}
const ehBloqueado = c => DADOS.bloqueados.includes(c);

// Libera o painel (outro site) a chamar esta API
app.use('/api', (req, res, next) => {
  res.set('Access-Control-Allow-Origin', '*');
  res.set('Access-Control-Allow-Headers', 'Content-Type, x-senha');
  res.set('Access-Control-Allow-Methods', 'GET, POST, PUT, OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});
// Loja pública: o site do cliente lê produtos, preços e links daqui
app.get('/api/loja', (_req, res) => res.json({ produtos: DADOS.produtos.map(({ id, nome, descricao, preco, link }) => ({ id, nome, descricao, preco, link })) }));

function senhaOk(req) {
  const s = String(req.get('x-senha') || req.body?.senha || '');
  return ADMIN_SENHA && s.length === ADMIN_SENHA.length && crypto.timingSafeEqual(Buffer.from(s), Buffer.from(ADMIN_SENHA));
}
app.use('/api/admin', (req, res, next) => {
  if (limite(req.ip)) return res.status(429).json({ ok: false, msg: 'Muitas tentativas, espere 1 minuto' });
  if (!ADMIN_SENHA || !SEGREDO) return res.json({ ok: false, msg: 'Configure SEGREDO e ADMIN_SENHA no Render' });
  if (!senhaOk(req)) return res.status(401).json({ ok: false, msg: 'Senha errada' });
  next();
});
function situacao(c) {
  if (ehBloqueado(c.codigo)) return 'bloqueado';
  return new Date(c.validade + 'T23:59:59-03:00') < Date.now() ? 'vencido' : 'ativo';
}
app.get('/api/admin/dados', (_req, res) => res.json({
  ok: true, persistente: !!(process.env.RENDER_API_KEY && process.env.RENDER_SERVICE_ID),
  produtos: DADOS.produtos,
  clientes: DADOS.clientes.map(c => ({ ...c, situacao: situacao(c) })).reverse()
}));
app.post('/api/admin/gerar', async (req, res) => {
  const prod = DADOS.produtos.find(p => p.id === req.body?.produto);
  const dias = Number(req.body?.dias) || prod?.dias || 30;
  const g = gerarCodigo(req.body?.nome, dias);
  DADOS.clientes.push({ codigo: g.codigo, nome: String(req.body?.nome || '').slice(0, 40), contato: String(req.body?.contato || '').slice(0, 60), produto: prod?.nome || '', validade: g.validade, criado: new Date().toISOString().slice(0, 10) });
  if (DADOS.clientes.length > 2000) DADOS.clientes = DADOS.clientes.slice(-2000);
  const s = await salvar();
  res.json({ ok: true, ...g, salvo: s.ok, aviso: s.msg });
});
app.post('/api/admin/bloquear', async (req, res) => {
  const c = String(req.body?.codigo || '').trim().toUpperCase();
  DADOS.bloqueados = DADOS.bloqueados.filter(x => x !== c);
  if (req.body?.bloquear !== false) DADOS.bloqueados.push(c);
  const s = await salvar(); res.json({ ok: true, salvo: s.ok, aviso: s.msg });
});
app.post('/api/admin/excluir', async (req, res) => {
  const c = String(req.body?.codigo || '').trim().toUpperCase();
  DADOS.clientes = DADOS.clientes.filter(x => x.codigo !== c);
  if (!DADOS.bloqueados.includes(c)) DADOS.bloqueados.push(c); // excluir também tira o acesso
  const s = await salvar(); res.json({ ok: true, salvo: s.ok, aviso: s.msg });
});
app.put('/api/admin/produtos', async (req, res) => {
  const l = Array.isArray(req.body?.produtos) ? req.body.produtos : null;
  if (!l) return res.json({ ok: false, msg: 'Lista inválida' });
  DADOS.produtos = l.slice(0, 20).map((p, i) => ({
    id: String(p.id || 'p' + Date.now() + i).slice(0, 30), nome: String(p.nome || 'Produto').slice(0, 60),
    descricao: String(p.descricao || '').slice(0, 200), preco: String(p.preco || '').slice(0, 30),
    link: /^https?:\/\//.test(p.link || '') ? String(p.link).slice(0, 500) : '', dias: Math.max(1, Math.min(3650, Number(p.dias) || 30))
  }));
  const s = await salvar(); res.json({ ok: true, produtos: DADOS.produtos, salvo: s.ok, aviso: s.msg });
});
app.get('/health', (_req, res) => res.json({ ok: true }));

// Uma conexão por @ do TikTok, compartilhada por todas as telas abertas
const lives = new Map(); // user -> { conn, sockets:Set, status }

function clean(u) {
  return String(u || '').trim().replace(/^https?:\/\/(www\.)?tiktok\.com\//, '').replace(/^@/, '').replace(/\/live.*$/, '').toLowerCase();
}

function userInfo(u) {
  return {
    id: u?.uniqueId || 'anonimo',
    nome: u?.nickname || u?.uniqueId || 'anonimo',
    foto: u?.profilePicture?.url?.[0] || u?.profilePictureUrl || ''
  };
}

async function openLive(user) {
  let live = lives.get(user);
  if (live) return live;
  const conn = new TikTokLiveConnection(user, { enableExtendedGiftInfo: true, processInitialData: false });
  live = { conn, sockets: new Set(), status: 'conectando' };
  lives.set(user, live);
  const room = 'live:' + user;
  const emit = (ev, data) => io.to(room).emit(ev, data);

  conn.on(WebcastEvent.CHAT, d => emit('chat', { ...userInfo(d.user), texto: d.comment || '' }));
  conn.on(WebcastEvent.LIKE, d => emit('like', { ...userInfo(d.user), qtd: d.likeCount || 1 }));
  conn.on(WebcastEvent.MEMBER, d => emit('entrou', userInfo(d.user)));
  conn.on(WebcastEvent.GIFT, d => {
    const tipo = d.giftDetails?.giftType;
    if (tipo === 1 && !d.repeatEnd) return; // espera o fim da sequência
    const qtd = d.repeatCount || 1;
    const moedas = d.giftDetails?.diamondCount || d.extendedGiftInfo?.diamond_count || 1;
    emit('presente', {
      ...userInfo(d.user),
      presente: d.giftDetails?.giftName || d.extendedGiftInfo?.name || 'Presente',
      qtd, moedas, total: moedas * qtd
    });
  });
  conn.on(WebcastEvent.STREAM_END, () => { emit('status', { status: 'live encerrada' }); closeLive(user); });
  conn.on('disconnected', () => emit('status', { status: 'desconectado' }));

  try {
    const st = await conn.connect();
    live.status = 'ao vivo';
    emit('status', { status: 'ao vivo', roomId: st.roomId });
  } catch (e) {
    lives.delete(user);
    const msg = /offline/i.test(String(e?.name || e?.message)) ? 'Esse @ não está ao vivo agora' : 'Não consegui ligar na live: ' + (e?.message || e);
    emit('status', { status: 'erro', msg });
  }
  return live;
}

function closeLive(user) {
  const live = lives.get(user);
  if (!live) return;
  try { live.conn.disconnect(); } catch {}
  lives.delete(user);
}

io.on('connection', socket => {
  let current = null;
  socket.on('entrar', async dados => {
    const raw = typeof dados === 'object' ? dados?.user : dados;
    const v = validaCodigo(typeof dados === 'object' ? dados?.codigo : '');
    if (!v.ok) return socket.emit('status', { status: 'erro', msg: v.msg + ' · abra o app e digite seu código', codigo: false });
    const user = clean(raw);
    if (!user) return socket.emit('status', { status: 'erro', msg: 'Digite seu @ do TikTok' });
    current = user;
    socket.join('live:' + user);
    const live = await openLive(user);
    if (lives.get(user)) {
      live.sockets.add(socket.id);
      socket.emit('status', { status: live.status });
    }
  });
  socket.on('disconnect', () => {
    if (!current) return;
    const live = lives.get(current);
    if (!live) return;
    live.sockets.delete(socket.id);
    if (live.sockets.size === 0) setTimeout(() => { const l = lives.get(current); if (l && l.sockets.size === 0) closeLive(current); }, 60000);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log('Renda Games rodando na porta ' + PORT));
